def repo_row(name="alpha", harnesses=None, scheduled=None, **kw) -> dict:
    row = {
        "repo": name,
        "nwo": f"bamr87/{name}",
        "category": "dev-tools",
        "status": "active",
        "external": False,
        "archived": False,
        "scanned": True,
        "manifest": False,
        "agent_context": "CLAUDE.md",
        "oauth_secret": "ok",
        "workflows_total": 1,
        "harnesses": harnesses if harnesses is not None else [],
        "scheduled": scheduled if scheduled is not None else [],
    }
    row.update(kw)
    return row


def harness_row(**kw) -> dict:
    row = {
        "workflow": "Claude",
        "path": ".github/workflows/claude.yml",
        "kind": "mention-handler",
        "triggers": ["issue_comment"],
        "crons": [],
        "action_ref": "v1",
        "auth": "oauth-first",
        "model": None,
        "max_turns": None,
        "max_budget_usd": None,
        "kit": "0.4.0",
        "kit_status": "current",
        "mention_handler": True,
    }
    row.update(kw)
    return row


