def test_classify_reads_the_ordered_auth_shape():
    """The 0.5.0 kit takes its credential from CLAUDE_AUTH_ORDER — configuration,
    not drift — and must not be graded as `auth-drift`."""
    ordered = MENTION_WF.replace(
        "anthropic_api_key: ${{ secrets.CLAUDE_CODE_OAUTH_TOKEN == '' && secrets.ANTHROPIC_API_KEY || '' }}",
        "anthropic_api_key: ${{ steps.claude-auth.outputs.method == 'api_key' && secrets.ANTHROPIC_API_KEY || '' }}",
    ).replace("      - uses: anthropics/claude-code-action@v1",
              "      - id: claude-auth\n        uses: bamr87/bamr87/.github/actions/claude-auth@main\n"
              "      - uses: anthropics/claude-code-action@v1")
    info = hr.classify_workflow(".github/workflows/claude.yml", ordered)
    assert info["auth"] == "ordered", info


def test_classify_mention_handler_reads_kit_auth_and_triggers():
    info = hr.classify_workflow(".github/workflows/claude.yml", MENTION_WF)
    assert info["ai"] and info["kind"] == "mention-handler", info
    assert info["auth"] == "oauth-first"
    assert info["kit"] == "0.4.0"
    assert info["action_ref"] == "v1"
    assert "issue_comment" in info["triggers"]
    assert info["crons"] == []


def test_classify_scheduled_agent_reads_cron_model_turns():
    info = hr.classify_workflow(".github/workflows/nightly.yml", SCHEDULED_WF)
    assert info["kind"] == "scheduled-agent"
    assert info["crons"] == ["0 6 * * *"]
    assert info["model"] == "opus"
    assert info["max_turns"] == 160
    assert info["max_budget_usd"] == 24.0
    assert info["auth"] == "oauth-only"
    assert info["kit"] is None


def test_mention_needs_a_mention_capable_trigger():
    # A dispatch-only fan-out whose HEADER COMMENT says "@claude" is not a
    # mention handler (the real fanout.yml (kit: standardize) false-positived on this).
    dispatch_only = (
        "name: fanout\n# seeds the @claude mention workflow\n"
        "on:\n  workflow_dispatch:\njobs:\n  x:\n    runs-on: ubuntu-latest\n"
        "    steps:\n      - uses: anthropics/claude-code-action@v1\n"
        "        with:\n          claude_code_oauth_token: x\n"
    )
    info = hr.classify_workflow(".github/workflows/fanout.yml", dispatch_only)
    assert info["ai"] and not info["mention_handler"] and info["kind"] == "event-agent", info


def test_classify_reads_gitfactory_provenance_and_kill_switch():
    info = hr.classify_workflow(".github/workflows/factory--issue-concierge.yml", FACTORY_LINE)
    assert info["factory"] == {"blueprint": ".factory/issue-concierge.blueprint.json",
                               "hash": "98d35f75"}, info["factory"]
    assert info["switch"] == "ISSUE_CONCIERGE_ENABLED"
    assert info["kind"] == "scheduled-agent"
    plain = hr.classify_workflow(".github/workflows/nightly.yml", SCHEDULED_WF)
    assert plain["factory"] is None and plain["switch"] is None
    ci = hr.classify_workflow(".github/workflows/ci.yml", PLAIN_CI)
    assert ci["factory"] is None and ci["switch"] is None  # facts exist for non-AI files too


def test_switch_missing_flags_only_unswitched_scheduled_agents():
    gated = repo_row(name="gated", harnesses=[harness_row(
        workflow="line", kind="scheduled-agent", crons=["0 3 * * *"], mention_handler=False,
        switch="LINE_ENABLED")])
    ungated = repo_row(name="ungated", harnesses=[harness_row(
        workflow="agent", kind="scheduled-agent", crons=["0 4 * * *"], mention_handler=False)])
    chat = repo_row(name="chat", harnesses=[harness_row()])  # mention handlers run only when asked
    repos = [gated, ungated, chat]
    for r in repos:
        r["est_scheduled_ai_per_day"] = hr.repo_schedule_load(r)
        hr.evaluate_coverage(r, CFG)
    items = hr.build_attention(repos, hr.build_throughput(repos, CFG, {}),
                               hr.build_trends({}, {}, CFG), CFG)
    flagged = [i["repo"] for i in items if i["kind"] == "switch-missing"]
    assert flagged == ["ungated"], flagged
    finding = next(i for i in items if i["kind"] == "switch-missing")
    assert "agent.yml" in finding["summary"] or ".github/workflows/claude.yml" in finding["summary"]
    assert "gate" in finding["action"]


def test_finalize_stamps_schema_marker_and_factory_totals():
    # The file is a consumed interface (GitFactory Fleet Studio, gitorio
    # specs/012): the marker is the first key, and the factory facts roll up.
    factory = repo_row(name="gitorio", factory=True, factory_blueprints=["blueprint.json"],
                       harnesses=[
                           harness_row(workflow="line", kind="scheduled-agent", crons=["0 3 * * *"],
                                       mention_handler=False, switch="GARDENER_ENABLED",
                                       factory={"blueprint": ".factory/blueprint.json", "hash": "abc123"}),
                           harness_row()])
    out = hr.finalize([factory, repo_row()], CFG, "0.4.0", {}, {}, "reused", None,
                      dt.datetime(2026, 9, 2, tzinfo=dt.timezone.utc))
    assert out["schema"] == hr.SCHEMA_MARKER == "harness-registry/v1"
    assert list(out)[0] == "schema"
    t = out["totals"]
    assert t["factory_repos"] == 1 and t["factory_lines"] == 1 and t["scheduled_switched"] == 1, t
    assert "GitFactory" in out["note"]
    row = next(r for r in out["repos"] if r["repo"] == "gitorio")
    assert row["factory"] is True and row["factory_blueprints"] == ["blueprint.json"]


def test_classify_non_ai_and_broken_yaml_degrade():
    info = hr.classify_workflow(".github/workflows/ci.yml", PLAIN_CI)
    assert not info["ai"] and "push" in info["triggers"]
    broken = "name: X\non:\n  schedule:\n    - cron: '0 5 * * 1'\n\t- bad-tab"
    info = hr.classify_workflow(".github/workflows/broken.yml", broken)
    assert info["parse_error"]
    assert info["crons"] == ["0 5 * * 1"], info  # regex fallback still sees it


