def test_coverage_grades_gaps_and_excuses_external_archived_exempt():
    bare = repo_row(name="bare", agent_context=None, oauth_secret="missing")
    hr.evaluate_coverage(bare, CFG)
    assert set(bare["coverage"]["missing"]) == {"mention-handler", "agent-context",
                                                "oauth-secret"}

    ok = repo_row(harnesses=[harness_row()])
    hr.evaluate_coverage(ok, CFG)
    assert ok["coverage"]["ok"] and not ok["coverage"]["missing"]

    ext = repo_row(name="skills", external=True, agent_context=None)
    arch = repo_row(name="old", archived=True, agent_context=None)
    unscanned = repo_row(name="dark", scanned=False, agent_context=None)
    cfg_exempt = dict(CFG, exempt=["special"])
    exempt = repo_row(name="special", agent_context=None)
    for row, cfg in ((ext, CFG), (arch, CFG), (unscanned, CFG), (exempt, cfg_exempt)):
        hr.evaluate_coverage(row, cfg)
        assert row["coverage"]["exempt"] and not row["coverage"]["missing"], row["repo"]


def test_gaps_are_fanout_deployable_only():
    rows = [
        repo_row(name="needs-handler", submodule=True),       # missing mention-handler
        repo_row(name="secret-only", harnesses=[harness_row()],
                 oauth_secret="missing", submodule=True),     # token-rotation's lane
        repo_row(name="stale-kit", submodule=True,
                 harnesses=[harness_row(kit="0.1.0", kit_status="upgradeable")]),
        repo_row(name="fine", harnesses=[harness_row()], submodule=True),
    ]
    for r in rows:
        hr.evaluate_coverage(r, CFG)
    with tempfile.NamedTemporaryFile("w", suffix=".yml", delete=False) as fh:
        yaml.safe_dump({"repos": rows}, fh)
        path = Path(fh.name)
    try:
        assert hr.fanout_gaps(path) == ["needs-handler", "stale-kit"]
        assert hr.fanout_gaps(Path("/nonexistent/registry.yml")) == []
    finally:
        path.unlink()


def test_gaps_include_registry_only_repos():
    """A repo does not need to be MOUNTED to be a fan-out target.

    fanout.sh clones the target fresh, so .gitmodules was only ever supplying a
    URL; it now falls back to the registry. While it did not, every unmounted
    repo was a dead end — bamr87/SCHEMA, the upstream of the linter this hub
    vendors, sat months with no mention handler because nothing could target
    it. What is still excluded is what the engine still refuses."""
    rows = [
        repo_row(name="sub-gap", submodule=True),
        repo_row(name="loose-gap", submodule=False),      # registry-only: now a target
        repo_row(name="ext-gap", submodule=False, external=True, nwo="other/ext-gap"),
        repo_row(name="arch-gap", submodule=True, archived=True),
    ]
    for r in rows:
        hr.evaluate_coverage(r, CFG)
    assert all(r["coverage"]["missing"] for r in rows[:2]), "fixture must have gaps"
    with tempfile.NamedTemporaryFile("w", suffix=".yml", delete=False) as fh:
        yaml.safe_dump({"repos": rows}, fh)
        path = Path(fh.name)
    try:
        assert hr.fanout_gaps(path) == ["sub-gap", "loose-gap"]
    finally:
        path.unlink()


def test_deployability_is_ownership_not_mounting():
    assert hr.is_deployable(repo_row(name="a", submodule=False)) is True
    assert hr.is_deployable(repo_row(name="a", external=True)) is False
    assert hr.is_deployable(repo_row(name="a", archived=True)) is False
    assert hr.is_deployable({"repo": "a"}) is False      # never scanned, no nwo


def test_unreachable_repos_have_no_gap_left_to_report():
    """The counterpart to the deleted `gap-not-deployable` finding: everything
    the fan-out still cannot reach is already excused by evaluate_coverage, so
    the class is empty rather than merely smaller."""
    rows = [repo_row(name="ext", external=True, nwo="other/ext"),
            repo_row(name="arch", archived=True)]
    for r in rows:
        hr.evaluate_coverage(r, CFG)
        assert not hr.is_deployable(r)
        assert not r["coverage"]["missing"], r["repo"]


def test_submodule_names_reads_the_registry():
    with tempfile.NamedTemporaryFile("w", suffix=".yml", delete=False) as fh:
        yaml.safe_dump({"projects": [
            {"name": "a", "submodule_path": "projects/a"},
            {"name": "b"},                       # registry-only repo
            {"name": "c", "submodule_path": ""},  # empty is not a path
        ]}, fh)
        path = Path(fh.name)
    try:
        assert hr.submodule_names(path) == {"a"}
    finally:
        path.unlink()


def test_kit_status_compares_against_hub_version():
    assert hr.kit_status("0.4.0", "0.4.0") == "current"
    assert hr.kit_status("0.1.0", "0.4.0") == "upgradeable"
    assert hr.kit_status("0.5.0", "0.4.0") == "ahead"
    assert hr.kit_status(None, "0.4.0") == "unstamped"
    assert hr.kit_status("0.4.0", None) == "unknown"


