def test_rotation_secret_states_count_an_applied_write_as_present():
    """The 2026-11-02 ledger: 13 repos the apply run wrote still read `missing`
    (the survey's pre-write state), which raised 13 false coverage-gap items."""
    def ledger(mode):
        return {"mode": mode, "tokens": [{"name": "CLAUDE_CODE_OAUTH_TOKEN", "repos": [
            {"nwo": "bamr87/new", "state": "missing", "action": "written"},
            {"nwo": "bamr87/broke", "state": "missing", "action": "failed"},
            {"nwo": "bamr87/had", "state": "ok", "action": "none"},
        ]}]}
    states = hr.rotation_secret_states(ledger("apply"))
    assert states == {"bamr87/new": "ok", "bamr87/broke": "missing", "bamr87/had": "ok"}
    # A dry run only planned the write, so the repo is still missing its secret.
    assert hr.rotation_secret_states(ledger("dry-run"))["bamr87/new"] == "missing"

    fixed = repo_row(name="new", harnesses=[harness_row()], oauth_secret=states["bamr87/new"])
    broke = repo_row(name="broke", harnesses=[harness_row()], oauth_secret=states["bamr87/broke"])
    for row in (fixed, broke):
        hr.evaluate_coverage(row, CFG)
    assert "oauth-secret" not in fixed["coverage"]["missing"]
    assert "oauth-secret" in broke["coverage"]["missing"]


def test_fleet_throughput_total_is_order_independent():
    """The fleet estimate is a float sum at a rounding knife-edge: the real
    fleet's per-repo loads total 10.605, which plain left-to-right addition
    rounds to 10.6 or 10.61 depending on repo order — churning the committed
    _data/harness_registry.yml on every daily refresh. fsum pins it."""
    loads = [0.429, 0.176, 2.143, 0.143, 4.143, 2.143, 1.428]
    cfg = {"throughput": {"max_scheduled_ai_per_day_fleet": 30,
                          "max_scheduled_ai_per_day_repo": 8,
                          "max_ai_crons_per_utc_hour": 3}}
    seen = set()
    for shift in range(len(loads)):
        order = loads[shift:] + loads[:shift]
        repos = [{"repo": f"r{i}", "est_scheduled_ai_per_day": v, "scheduled": []}
                 for i, v in enumerate(order)]
        seen.add(hr.build_throughput(repos, cfg, {})["est_scheduled_ai_per_day"])
    assert len(seen) == 1, f"fleet total varies with repo order: {sorted(seen)}"


def test_repo_schedule_load_is_order_independent():
    crons = ["0 6 * * *", "17 3 * * 1", "0 */4 * * *", "30 2 1 * *"]
    a = hr.repo_schedule_load({"harnesses": [{"crons": crons}]})
    b = hr.repo_schedule_load({"harnesses": [{"crons": list(reversed(crons))}]})
    assert a == b, f"{a} != {b}"


def test_trends_price_actions_from_the_billing_meter_when_present():
    """The proxy ranks; the meter prices. This is the sensor for the phantom
    287k-minute breach the proxy published in 2026-09 while GitHub billed ~24k."""
    days = [{"date": f"2026-09-0{d}", "total_min": 9000.0} for d in range(1, 8)]   # proxy: ~274k/month
    act = {"by_day": days, "billing": {
        "days_elapsed": 5, "minutes_this_month": 6239.0, "run_rate_monthly": 37983.0,
        "previous_month": "2026-08", "minutes_previous_month": 21891.0}}
    t = hr.build_trends({}, act, CFG)["actions_minutes"]
    assert t["source"] == "billing" and t["proxy_projected_monthly"] > 200000, t
    # under a week of the month elapsed, the last FULL month is the projection
    assert t["projected_monthly"] == 21891.0 and t["status"] == "ok", t
    assert t["mom_delta_pct"] == 0.0
    # a full week in: the run-rate takes over, and growth is month-over-month
    act["billing"]["days_elapsed"] = 10
    t = hr.build_trends({}, act, CFG)["actions_minutes"]
    assert t["projected_monthly"] == 37983.0 and t["mom_delta_pct"] == 73.5, t
    assert t["status"] == "growing", t["status"]
    # the ceiling is judged on billed minutes, never on the proxy
    tight = dict(CFG, budget={**CFG["budget"], "monthly_actions_minutes": 30000})
    assert hr.build_trends({}, act, tight)["actions_minutes"]["status"] == "breach"
    # an errored billing block leaves the proxy in charge, and says nothing about billing
    act["billing"] = {"error": "403 scope"}
    t = hr.build_trends({}, act, CFG)["actions_minutes"]
    assert "source" not in t and t["projected_monthly"] > 200000


