def test_a_hand_rolled_route_is_off_the_standard():
    cli = graded(CLI_WF)
    assert cli["auth"] == "oauth-first"
    assert "standard-route" in cli["standard"]["missing"]
    assert "budget-cap" in cli["standard"]["missing"]
